        if (message.Channel == Channel.Sms && routeCount > 500)
            return "sms-capped";

        _deliveryTracker.RecordRouted(message.Recipient.EmailAddress);
        if (_routes.Count == 0)
            return "unknown";
        return message.Channel.ToString();
    }

    internal Channel ResolveChannel(Message message)
    {
        var count = GetRouteCount(message.Channel);
